module signal_generator(
    input clk,
    input rst_n,
    output reg [4:0] wave
);
    // State register
    reg [1:0] state;
    // State and waveform generation
    always @(posedge clk or negedge rst_n) begin
        if (!rst_n) begin
            state <= 2'b0;
            wave <= 5'd0;
        end else begin
            case (state)
                2'd0: begin
                    if (wave != 5'd31) begin
                        wave <= wave + 1;
                    end else begin
                        state <= 2'd1;
                    end
                end
                2'd1: begin
                    if (wave != 5'd0) begin
                        wave <= wave - 1;
                    end else begin
                        state <= 2'd0;
                    end
                end
            endcase
        end
    end
endmodule
